const buildTimes={wall:10,tower:35,bastion:55,depot:25,base:65,barracks:40,forge:45,roost:45,altar:50,mill:30,armory:35,foundry:40};
function assignBuilder(worker,building,append=true){if(worker.order?.target===building||worker.tasks?.some(t=>t.target===building))return;queueTask(worker,{kind:'build',target:building},append);}

function constructionTick(b,dt){const c=b.construction;if(!c)return;const active=state.entities.find(w=>w.owner===b.owner&&w.type==='worker'&&w.hp>0&&w.order?.kind==='build'&&w.order.target===b&&Math.hypot(w.x-b.x,w.y-b.y)<=b.size+32&&Math.abs(terrainHeight(w.x,w.y)-terrainHeight(b.x,b.y))<2);c.active=!!active;if(active){const worked=Math.min(c.left,dt);c.left=Math.max(0,c.left-dt);b.hp=Math.min(b.max,b.hp+b.max*.8*worked/c.total);}if(c.left<=0){b.construction=null;if(b.type==='wall'){state.wallVersion++;state.blockCache={};}if(b.owner===0)toast(buildings[b.type].name+' completed.');}}
function separateUnits(){const troops=state.entities.filter(e=>!e.building&&e.hp>0&&!e.hiddenInMine);for(let pass=0;pass<3;pass++)for(let i=0;i<troops.length;i++)for(let j=i+1;j<troops.length;j++){const a=troops[i],b=troops[j];if((isFlying(a))!==(isFlying(b)))continue;let dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy),min=a.size+b.size+8;if(d>=min)continue;if(d<.001){const angle=(a.id*7+b.id)*2.399;dx=Math.cos(angle);dy=Math.sin(angle);d=1;}const amount=(min-d)*.5;for(const [e,sign] of [[a,-1],[b,1]]){const x=Math.max(10,Math.min(SIZE-10,e.x+sign*dx/d*amount)),y=Math.max(10,Math.min(SIZE-10,e.y+sign*dy/d*amount));if(isFlying(e)||clearWallLine(e,x,y)){e.x=x;e.y=y;}}}}
function workItems(){const items=[];for(const b of state.entities.filter(e=>e.owner===0&&e.hp>0)){if(b.construction)items.push({label:buildings[b.type].name,detail:b.construction.active?'Constructing':'Waiting for builder',left:b.construction.left,total:b.construction.total});let researchWait=0;for(const r of researchJobs(b)){items.push({label:researchLabel(r.key,b.owner)+' '+r.level,detail:(researchWait?'Queued · ':'Researching · ')+buildings[b.type].name,left:r.left,total:r.total,wait:researchWait,buildingId:b.id,jobId:'research:'+r.id});researchWait+=r.left;}let wait=0;for(const q of b.queue){items.push({label:names[state.players[0].faction][q.type],detail:wait?'Queued · '+buildings[b.type].name:'Training · '+buildings[b.type].name,left:q.left,total:q.total,wait,buildingId:b.id,jobId:q.id});wait+=q.left;}}return items;}
function updateWorkQueue(){const items=workItems();$('workItems').innerHTML=items.length?items.map(i=>`<div class="work-item"><b>${i.label}</b><span>${i.detail}</span><progress max="${i.total}" value="${i.wait?0:i.total-i.left}"></progress>${i.jobId!==undefined?'<button class=cancel-work data-building='+i.buildingId+' data-cancel='+i.jobId+' aria-label="Cancel '+i.label+'">Cancel</button>':''}<small>${i.detail==='Waiting for builder'?'Paused · ':i.wait?'Starts in '+Math.ceil(i.wait)+'s · ':''}${Math.ceil(i.left)}s ${i.detail==='Resource remaining'?'to depletion':'remaining'}</small></div>`).join(''):'<p class="work-empty">No work in progress</p>';}
