function heroAbility(hero,aiControlled=false){if(!state||paused||state.count>0||state.ended||hero.owner!==0&&!aiControlled||!isHeroType(hero.type)||hero.hp<=0||(hero.abilityReady||0)>state.time)return false;
 if(hero.type!=='hero')return alternateHeroAbility(hero);hero.abilityReady=state.time+20*heroCooldown(hero);if(heroRank(hero,'battleborn'))hero.rageUntil=state.time+3+heroRank(hero,'battleborn')*2;hero.action={kind:'attack',duration:.8,until:state.time+.8};const human=state.players[hero.owner].faction==='human';
 if(human){for(const ally of state.entities)if(ally.owner===hero.owner&&!ally.building&&ally.hp>0&&Math.hypot(ally.x-hero.x,ally.y-hero.y)<=190){ally.shieldUntil=state.time+5;ally.hp=Math.min(ally.max,ally.hp+35*heroRank(hero,'renewal'));burst(ally.x,ally.y,'magic',hero.owner);}if(hero.owner===0)toast('Aegis Shield: nearby troops protected for 5 seconds.');}
 else{for(const enemy of state.entities)if(enemy.owner!==hero.owner&&enemy.hp>0&&Math.hypot(enemy.x-hero.x,enemy.y-hero.y)<=150){enemy.hp-=55*shieldMultiplier(enemy);enemy.hitUntil=state.time+.2;burst(enemy.x,enemy.y,'blast',hero.owner);}if(hero.owner===0)toast('Dominion Cleave strikes nearby enemies.');}return true;
}
function shieldMultiplier(e){return e.shieldUntil>state.time?.5:1;}

function stopUnit(e){leaveMine(e);e.manualPassive=true;e.order={kind:'stop'};e.action=null;e.shot=null;e.route=null;e.walkUntil=0;e.jobs=[];e.tasks=[];}
function renderBuildingQueues(){const producers=selected.filter(e=>e.owner===0&&e.building&&!e.construction);if(!producers.length)return;const panel=$('queue');panel.innerHTML='';for(const b of producers){const box=document.createElement('div');box.className='building-queue';const title=document.createElement('b');title.textContent=buildings[b.type].name+' #'+b.id;box.appendChild(title);let wait=0;for(const q of b.queue){const row=document.createElement('div');row.innerHTML='<span>'+names[state.players[b.owner].faction][q.type]+' · '+Math.ceil(q.left)+'s'+(wait?' · starts in '+Math.ceil(wait)+'s':' · training')+'</span><progress max="'+q.total+'" value="'+(wait?0:q.total-q.left)+'"></progress>';const cancel=document.createElement('button');cancel.textContent='Cancel';cancel.onclick=()=>cancelProduction(b.id,String(q.id));row.appendChild(cancel);box.appendChild(row);wait+=q.left;}let researchWait=0;for(const r of researchJobs(b)){const row=document.createElement('div');row.innerHTML='<span>'+researchLabel(r.key,b.owner)+' '+r.level+' · '+Math.ceil(r.left)+'s'+(researchWait?' · starts in '+Math.ceil(researchWait)+'s':' · researching')+'</span><progress max="'+r.total+'" value="'+(researchWait?0:r.total-r.left)+'"></progress>';const cancel=document.createElement('button');cancel.textContent='Cancel';cancel.onclick=()=>cancelProduction(b.id,'research:'+r.id);row.appendChild(cancel);box.appendChild(row);researchWait+=r.left;}if(!b.queue.length&&!b.research){const idle=document.createElement('small');idle.textContent='Idle — no work queued';box.appendChild(idle);}panel.appendChild(box);}}

