function stopSelected(){const troops=selected.filter(e=>e.owner===0&&!e.building&&e.hp>0);troops.forEach(stopUnit);commandMode=null;placement=null;drag=null;orderMarker=null;if(troops.length)toast('Stopped '+troops.length+' troops. They will stay idle until given an order.');updateUI();}
function heroAuraDescription(faction){return faction==='human'?'Sun Marshal · Protection aura: friendly troops within 190 units take 30% less attack damage. Buildings are not protected.':'Stormcaller · Fury aura: friendly troops within 190 units deal 30% more attack damage. Buildings receive no damage bonus.';}

function isFlying(e){return !e.building&&(!!units[e.type]?.flying||e.type==='hero3'&&state.players[e.owner].faction==='horde');}
function rememberEnemyBuildings(){
 state.enemyBuildings??={};
 for(const e of state.entities)if(e.owner!==0&&e.building&&visible(e.x,e.y)&&e.hp>0)state.enemyBuildings[e.id]={id:e.id,type:e.type,x:e.x,y:e.y};
 for(const [id,mark] of Object.entries(state.enemyBuildings))if(visible(mark.x,mark.y)&&!state.entities.some(e=>e.id===Number(id)&&e.hp>0))delete state.enemyBuildings[id];
}
