 horde:[['whirlaxe','Whirling axe','Spin the axe to strike nearby enemies.','training'],['battleborn','Battleborn','Dominion Cleave grants a longer battle rage.','whirlaxe',false],['ironhide','Iron hide','Brace behind a protective guard.','training'],['quakeslam','Quake slam','Strike and stun nearby enemies.','whirlaxe'],['frenzy','Frenzy','Rush toward foes with increased speed and damage.','quakeslam'],['axerush','Axe rush','A guarded rush toward nearby foes.','ironhide'],['warleap','War leap','A protected advance that damages nearby foes.','axerush'],['cleave','Titan cleave','A heavy axe sweep deals wide area damage.','frenzy'],['ragequake','Rage quake','A powerful quake damages and stuns nearby foes.','cleave']]
