function makePlateaus(map){const shift=map==='canyon'?100:map==='frontier'?-80:0;return [{x:640+shift,y:750,w:360,h:320,height:32,rampX:820+shift},{x:1410,y:1050+shift,w:380,h:350,height:64,rampX:1600},{x:900,y:1700,w:340,h:280,height:32,rampX:1070}];}
function onRamp(x,y){return (state?.plateaus||[]).some(p=>Math.abs(x-p.rampX)<64&&Math.abs(y-(p.y+p.h))<80);}
function terrainHeight(x,y){for(const p of state?.plateaus||[]){if(Math.abs(x-p.rampX)<64&&y>=p.y+p.h-80&&y<=p.y+p.h+80)return p.height*(p.y+p.h+80-y)/160;if(x>p.x&&x<p.x+p.w&&y>p.y&&y<p.y+p.h)return p.height;}return 0;}
function renderAltitude(e){return isFlying(e)?e.flightAltitude??terrainHeight(e.x,e.y)+24:terrainHeight(e.x,e.y);}
function surfacePoint(p){if(!state?.plateaus?.length)return p;for(const height of [64,32])if(Math.abs(terrainHeight(p.x,p.y+height)-height)<1)return{x:p.x,y:p.y+height};for(let h=64;h>=0;h-=2)if(Math.abs(terrainHeight(p.x,p.y+h)-h)<1.1)return{x:p.x,y:p.y+h};return p;}
function cliffObstacles(){const result=[];for(const p of state?.plateaus||[]){for(let x=p.x;x<=p.x+p.w;x+=24){result.push({x,y:p.y,half:12});if(Math.abs(x-p.rampX)>65)result.push({x,y:p.y+p.h,half:12});}for(let y=p.y;y<=p.y+p.h;y+=24)for(const x of [p.x,p.x+p.w])result.push({x,y,half:12});}return result;}
function flatBuildingSite(x,y,size){if(riverAt(x,y,size+12)||onRamp(x,y))return false;const h=terrainHeight(x,y);return [[-size,-size],[size,-size],[-size,size],[size,size]].every(([dx,dy])=>Math.abs(terrainHeight(x+dx,y+dy)-h)<1)&&!cliffObstacles().some(c=>Math.abs(c.x-x)<size+c.half&&Math.abs(c.y-y)<size+c.half);}
function drawPlateaus(g){for(const p of state.plateaus||[]){const h=p.height;g.fillStyle='#564b3e';g.fillRect(p.x,p.y-h,p.w,p.h+h);const cliffShade=g.createLinearGradient(0,p.y+p.h-h,0,p.y+p.h);cliffShade.addColorStop(0,'#aaa18b');cliffShade.addColorStop(.45,'#81786a');cliffShade.addColorStop(1,'#49483d');g.fillStyle=cliffShade;g.fillRect(p.x,p.y+p.h-h,p.w,h);g.strokeStyle='#383b3277';g.lineWidth=1;for(let row=0;row<h;row+=9){g.beginPath();for(let x=0;x<=p.w;x+=8){const y=p.y+p.h-h+row+Math.sin(x*.055+row)*2;x?g.lineTo(p.x+x,y):g.moveTo(p.x+x,y);}g.stroke();for(let col=12;col<p.w;col+=47){const x=p.x+col+Math.sin(row+col)*7,y=p.y+p.h-h+row;g.beginPath();g.moveTo(x,y);g.lineTo(x+3,y+4);g.lineTo(x-2,y+8);g.stroke();}}for(let i=0;i<600;i++){g.fillStyle=i%3?'#e0d5bd22':'#26352d33';g.fillRect(p.x+(i*43)%p.w,p.y+p.h-h+(i*17)%h,1+i%3,1);}g.fillStyle=h>=64?'#526d45':'#63834d';g.fillRect(p.x,p.y-h,p.w,p.h);g.strokeStyle='#98a069';g.strokeRect(p.x+3,p.y-h+3,p.w-6,p.h-6);for(let i=0;i<3000;i++){const x=p.x+((i*37)%p.w),y=p.y-h+((i*61)%p.h);g.strokeStyle=i%4===0?'#d0c579bb':i%3?'#89aa5cbb':'#203d2bcc';g.beginPath();g.moveTo(x,y);g.lineTo(x+2,y-4);g.stroke();}for(let i=0;i<45;i++){const x=p.x+12+(i*71)%(p.w-24),y=p.y-h+12+(i*47)%(p.h-24);g.fillStyle=i%3?'#adad8077':'#d6bc6977';g.beginPath();g.ellipse(x,y,2+i%3,1.5,0,0,Math.PI*2);g.fill();}g.fillStyle='#a39770';g.beginPath();g.moveTo(p.rampX-64,p.y+p.h-80-h);g.lineTo(p.rampX+64,p.y+p.h-80-h);g.lineTo(p.rampX+64,p.y+p.h+80);g.lineTo(p.rampX-64,p.y+p.h+80);g.closePath();g.fill();g.strokeStyle='#746b4f';for(let i=0;i<12;i++){const y=p.y+p.h-80-h+i*(160+h)/12;g.beginPath();g.moveTo(p.rampX-62,y);g.lineTo(p.rampX+62,y);g.stroke();}}}
function strongholdDefenses(base){base.towerCooldowns??=[0,0];for(let i=0;i<2;i++){if((base.towerCooldowns[i]||0)>state.time)continue;const ox=base.x+(i?1:-1)*35,oy=base.y-25,target=state.entities.filter(e=>e.owner!==base.owner&&e.hp>0&&!e.hiddenInMine&&Math.hypot(e.x-ox,e.y-oy)<300&&canSee(base.owner,e.x,e.y)).sort((a,b)=>Math.hypot(a.x-ox,a.y-oy)-Math.hypot(b.x-ox,b.y-oy))[0];if(!target)continue;base.towerCooldowns[i]=state.time+1.2;target.hp-=24*armorMultiplier(target)*shieldMultiplier(target);base.defenseShots??=[];base.defenseShots[i]={fromX:ox,fromY:oy-40,x:target.x,y:target.y,left:.35,duration:.35};burst(target.x,target.y,'hit',base.owner);}}
function drawStrongholdTowers(e,p){if(e.type!=='base'||(e.level||1)<3||e.construction)return;for(const x of [-66,66]){ctx.save();ctx.translate(x,-30);if(typeof worldSprite==='function')worldSprite('tower'+(p.faction==='horde'?'-dominion':''),65);else{ctx.fillStyle='#919b83';ctx.fillRect(-10,-35,20,40);}ctx.restore();}for(const shot of e.defenseShots||[])if(shot){shot.left=Math.max(0,shot.duration-(state.time-(shot.born??=state.time)));}}

let adminEnabled=false,pigEnabled=false;
function spawnRainbowPig(){if(!state||state.ended)return null;const base=state.entities.find(e=>e.owner===0&&e.type==='base'&&e.hp>0&&!e.construction);if(!base)return null;const pig=entity('pig',0,base.x,Math.min(SIZE-20,base.y+base.size+45));pig.flightAltitude=terrainHeight(pig.x,pig.y)+24;pig.rainbow=[];return pig;}
$('adminUnlock').onclick=()=>{const code=$('adminCode').value.trim().toUpperCase();if(code==='RYANISKING'){if(state){state.adminResources=true;state.players[0].gold=state.players[0].wood=1e9;updateUI();}adminEnabled=true;$('adminStatus').textContent='Unlimited resources enabled for this session.';}else if(code==='WHOLETTHEPIGSOUT'){if(state&&!spawnRainbowPig()){$('adminStatus').textContent='A living, completed player Stronghold is needed to summon the pig.';return;}pigEnabled=true;$('adminStatus').textContent=state?'Rainbow Laser Pig summoned at your Stronghold!':'Rainbow Laser Pig will appear at your Stronghold when your next battle starts.';if(state)updateUI();}else $('adminStatus').textContent='Incorrect code.';};
function drawRainbowTrails(){const colors=['#ff596e','#ffab45','#ffe66e','#6be48d','#64c9ff','#977dff','#ef8de4'];for(const pig of state.entities){if(pig.type!=='pig'||pig.hp<=0||pig.owner!==0&&!visible(pig.x,pig.y))continue;const points=pig.rainbow||[];ctx.save();ctx.lineCap='round';for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy);if(d<.1)continue;ctx.globalAlpha=Math.max(0,1-(state.time-a.time)/1.4)*.8;for(let band=0;band<colors.length;band++){const offset=(band-3)*2;ctx.strokeStyle=colors[band];ctx.lineWidth=2.5;ctx.beginPath();ctx.moveTo(a.x-dy/d*offset,a.y+dx/d*offset);ctx.lineTo(b.x-dy/d*offset,b.y+dx/d*offset);ctx.stroke();}}ctx.restore();}}
function drawPigLasers(e,s){const sy=s.fromY-(s.fromHeight??24),ty=s.y-(s.toHeight??0),angle=Math.atan2(ty-sy,s.x-s.fromX),nx=-Math.sin(angle)*3,ny=Math.cos(angle)*3;ctx.save();ctx.globalAlpha=Math.min(1,s.left/.08);ctx.lineCap='round';ctx.shadowColor='#ff389b';ctx.shadowBlur=12;for(const side of [-1,1]){ctx.beginPath();ctx.moveTo(s.fromX+nx*side,sy+ny*side);ctx.lineTo(s.x+nx*side,ty+ny*side);ctx.strokeStyle='#ff278d';ctx.lineWidth=4;ctx.stroke();ctx.strokeStyle='#fff2fc';ctx.lineWidth=1.2;ctx.stroke();}ctx.restore();}

function blockedGroundPoint(x,y,size){return groundObstacles().some(o=>Math.abs(x-o.x)<o.half+size&&Math.abs(y-o.y)<o.half+size);}

function resourceApproach(e,r){const candidates=[];for(let i=0;i<16;i++){const a=i*Math.PI/8,x=r.x+Math.cos(a)*22.5,y=r.y+Math.sin(a)*22.5;if(!blockedGroundPoint(x,y,e.size)&&Math.abs(terrainHeight(x,y)-terrainHeight(r.x,r.y))<2)candidates.push({x,y});}return candidates.sort((a,b)=>Math.hypot(e.x-a.x,e.y-a.y)-Math.hypot(e.x-b.x,e.y-b.y))[0];}
function approachResource(e,r,dt){const approach=resourceApproach(e,r);if(approach){move(e,approach.x,approach.y,dt,.2);return;}const next=state.resources.filter(t=>t!==r&&t.type==='wood'&&t.amount>0&&treeAvailable(t,e)&&resourceApproach(e,t)).sort((a,b)=>Math.hypot(e.x-a.x,e.y-a.y)-Math.hypot(e.x-b.x,e.y-b.y))[0];if(next)e.order.target=next;}

// Resource hit areas follow the visible canopy and mine artwork, including raised terrain.
function findResourceAt(p){const y=p.screenY??p.y-terrainHeight(p.x,p.y);return state.resources.filter(r=>{if(r.amount<=0||!visible(r.x,r.y))return false;const dy=y-(r.y-terrainHeight(r.x,r.y));return r.type==='wood'?Math.abs(p.x-r.x)<=26&&dy>=-65&&dy<=20:Math.abs(p.x-r.x)<=43&&dy>=-55&&dy<=30;}).sort((a,b)=>{const score=r=>Math.abs(p.x-r.x)+Math.abs(y-(r.y-terrainHeight(r.x,r.y)-(r.type==='wood'?28:10)));return score(a)-score(b);})[0]||null;}

function isHeroType(type){return ['hero','hero2','hero3'].includes(type);}
function heroAbilityName(h){if(h.type==='hero')return state.players[h.owner].faction==='human'?'Aegis Shield':'Dominion Cleave';return state.players[h.owner].faction==='human'?(h.type==='hero2'?'Arcane Nova':'Piercing Volley'):(h.type==='hero2'?'Witch Hex':'Dragonfire Breath');}
function heroAbilityDescription(h){const human=state.players[h.owner].faction==='human';if(h.type==='hero')return human?'Nearby allies take 50% less damage for 5s':'55 damage to nearby enemies · 20s cooldown';return human?(h.type==='hero2'?'85 arcane damage within 190 · 20s cooldown':'95 damage in a piercing line · 20s cooldown'):(h.type==='hero2'?'60 damage and 3s stun within 170 · 20s cooldown':'90 damage and 4s burning within 190 · 20s cooldown');}
function heroAuraText(h){const human=state.players[h.owner].faction==='human';if(h.type==='hero')return heroAuraDescription(human?'human':'horde');return names[human?'human':'horde'][h.type]+' · '+(human?(h.type==='hero2'?'Arcane focus: ranged infantry and other ranged heroes within 190 deal 15% more damage.':'Trailblazer: friendly troops within 190 move 15% faster.'):(h.type==='hero2'?'Witch renewal: friendly troops within 190 recover 2 health per second.':'Dragon dominion: friendly troops within 190 deal 15% more attack damage.'));}
function hasNearbyHero(e,type){return state.entities.some(h=>h.owner===e.owner&&h.type===type&&h.hp>0&&Math.hypot(h.x-e.x,h.y-e.y)<=190);}
function alternateHeroAbility(h){h.abilityReady=state.time+20*heroCooldown(h);h.action={kind:'attack',duration:.8,until:state.time+.8};const human=state.players[h.owner].faction==='human',range=h.type==='hero2'?(human?190:170):human?320:190;
 const foes=state.entities.filter(e=>e.owner!==h.owner&&e.hp>0&&!e.hiddenInMine&&canSee(h.owner,e.x,e.y)&&Math.hypot(e.x-h.x,e.y-h.y)<=range);
 for(const e of foes){const dx=e.x-h.x,dy=e.y-h.y;if(human&&h.type==='hero3'&&(dx*Math.cos(h.facing)+dy*Math.sin(h.facing)<0||Math.abs(dx*Math.sin(h.facing)-dy*Math.cos(h.facing))>55))continue;const base=human?(h.type==='hero2'?85:95):(h.type==='hero2'?60:90);e.hp-=base*(1+.1*heroRank(h,'potency'))*shieldMultiplier(e);if(!human){if(h.type==='hero2')e.stunUntil=state.time+3;else e.burn={left:4};}e.hitUntil=state.time+.3;burst(e.x,e.y,human?'magic':'blast',h.owner,.7);}burst(h.x,h.y,'magic',h.owner,.8);return true;}
function drawHeroSparks(e,p){if(e.type!=='hero'||p.faction!=='horde')return;ctx.save();ctx.strokeStyle='#b4ecff';ctx.lineWidth=1;ctx.shadowColor='#55b9ff';ctx.shadowBlur=5;for(let i=0;i<7;i++){const t=state.time*9+i*2.4;if(Math.sin(t*1.7)<.2)continue;const x=Math.cos(t)*25,y=-25+Math.sin(t*.8)*22;ctx.beginPath();ctx.moveTo(x-3,y-5);ctx.lineTo(x+2,y-1);ctx.lineTo(x-1,y+2);ctx.lineTo(x+3,y+6);ctx.stroke();}ctx.restore();}

// Rivers have shallow banks and explicit bridge openings for ground pathfinding.
function makeRivers(map){const points=[];for(let y=80;y<=2320;y+=24){let x=1200+Math.sin(y/210+(map==='canyon'?1:map==='frontier'?2:0))*62;if(y>1450&&y<2240){const t=y<1700?(y-1450)/250:y>1980?(2240-y)/260:1;x=Math.max(x,x+(1325-x)*Math.max(0,Math.min(1,t)));}points.push({x,y});}return [{points,width:44,bridges:[480,1480,2220]}];}
function riverCenter(river,y){const p=river.points;if(y<p[0].y||y>p[p.length-1].y)return null;const i=Math.min(p.length-2,Math.max(0,Math.floor((y-p[0].y)/24))),a=p[i],b=p[i+1];return a.x+(b.x-a.x)*(y-a.y)/(b.y-a.y);}
function riverAt(x,y,margin=0){return (state?.rivers||[]).some(r=>{const center=riverCenter(r,y);return center!==null&&Math.abs(x-center)<r.width/2+margin;});}
function riverObstacles(){const obstacles=[];for(const r of state?.rivers||[])for(const p of r.points)if(!r.bridges.some(y=>Math.abs(p.y-y)<58))obstacles.push({x:p.x,y:p.y,half:r.width/2});return obstacles;}
function drawRivers(g){for(const r of state.rivers||[]){g.lineJoin='round';g.lineCap='round';const path=()=>{g.beginPath();r.points.forEach((p,i)=>i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y));};path();g.strokeStyle='#6b7050';g.lineWidth=r.width+27;g.stroke();path();g.strokeStyle='#b2a67a';g.lineWidth=r.width+14;g.stroke();path();g.strokeStyle='#255b70';g.lineWidth=r.width;g.stroke();path();g.strokeStyle='#438a9c';g.lineWidth=r.width*.65;g.stroke();for(let i=0;i<r.points.length;i+=2){const p=r.points[i];for(const side of [-1,1]){g.fillStyle=i%3?'#778879':'#b4bc9b';g.beginPath();g.ellipse(p.x+side*(r.width/2+8),p.y,3+i%4,2+i%3,.7,0,Math.PI*2);g.fill();g.strokeStyle='#445b36';g.lineWidth=1;g.beginPath();g.moveTo(p.x+side*(r.width/2+15),p.y+4);g.lineTo(p.x+side*(r.width/2+16),p.y-5);g.stroke();}}for(const y of r.bridges){const x=riverCenter(r,y);g.fillStyle='#543c29';g.fillRect(x-69,y-36,138,72);for(let i=0;i<18;i++){g.fillStyle=i%3?'#a17c4f':'#bc9564';g.fillRect(x-68+i*7.6,y-34,6.6,68);}g.strokeStyle='#e0c99a';g.lineWidth=3;for(const dy of [-34,34]){g.beginPath();g.moveTo(x-70,y+dy);g.lineTo(x+70,y+dy);g.stroke();for(const dx of [-65,-35,0,35,65]){g.fillStyle='#6b4e33';g.fillRect(x+dx-2,y+dy-4,4,8);}}}}}
function drawRiverRipples(){ctx.save();ctx.lineWidth=1;ctx.strokeStyle='#a4dfe077';for(const r of state.rivers||[])for(let i=0;i<r.points.length;i+=3){const p=r.points[i];if(p.x<cam.x-40||p.x>cam.x+viewport.width+40||p.y<cam.y||p.y>cam.y+viewport.height||r.bridges.some(y=>Math.abs(p.y-y)<38))continue;const t=state.time*12+i,x=p.x+Math.sin(t*.12)*8,y=p.y+t%12;ctx.beginPath();ctx.moveTo(x-9,y);ctx.quadraticCurveTo(x,y+3,x+9,y);ctx.stroke();}ctx.restore();}

function battleAuraMultiplier(e){const human=state.players[e.owner].faction==='human';return human?(['ranged','sniper','hero2','hero3'].includes(e.type)&&hasNearbyHero(e,'hero2')?1.15:1):(hasNearbyHero(e,'hero3')?1.15:1);}
function researchLabel(key,owner=0){if(key.startsWith('hero:'))return heroTree(state.players[owner].faction).find(n=>n.id===key.slice(5))?.name||'Hero training';return ({lumber:'Lumber harvesting',goldMining:'Gold mining',infantry:'Infantry training',artillery:'Artillery training',capacity:'Collector capacity',stronghold:'Stronghold',fire:state.players[owner].faction==='human'?'Fire arrows':'Fire spears'})[key]||key;}

function setRally(building,rally){building.rally=rally;}

function canSee(owner,x,y){if(state.networkSight){const cx=Math.floor(x/CELL),cy=Math.floor(y/CELL);return cx>=0&&cy>=0&&cx<N&&cy<N&&!!state.networkSight[owner]?.[cy*N+cx];}return owner!==0||visible(x,y);}

function researchJobs(b){return [b.research,...(b.researchQueue||[])].filter(Boolean);}
function completedResearchLevel(b,key){return key==='stronghold'?(b.level||1):key.startsWith('hero:')?(state.players[b.owner].heroTech?.[key.slice(5)]||0):state.players[b.owner][key]||0;}
function projectedResearchLevel(b,key){return Math.max(completedResearchLevel(b,key),...researchJobs(b).filter(r=>r.key===key).map(r=>r.level));}
function enqueueResearch(b,r){r.id=++uid;b.researchQueue??=[];if(!b.research)b.research=r;else b.researchQueue.push(r);}
function refundResearch(b,r){state.players[b.owner].gold+=r.gold||0;state.players[b.owner].wood+=r.wood||0;}
function validResearchJob(b,r,levels){const current=levels[r.key]??completedResearchLevel(b,r.key);if(r.level!==current+1)return false;if(r.key.startsWith('hero:')){const node=heroTree(state.players[b.owner].faction).find(n=>n.id===r.key.slice(5));if(node?.requires&&!(levels['hero:'+node.requires]??completedResearchLevel(b,'hero:'+node.requires)))return false;}levels[r.key]=r.level;return true;}
function validateResearchQueue(b){const levels={};if(b.research)levels[b.research.key]=b.research.level;b.researchQueue=(b.researchQueue||[]).filter(r=>{if(validResearchJob(b,r,levels))return true;refundResearch(b,r);return false;});}
function promoteResearch(b){while(b.researchQueue?.length&&!b.research){const r=b.researchQueue.shift();if(validResearchJob(b,r,{}))b.research=r;else refundResearch(b,r);}}

$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('game').requestFullscreen();}catch{toast('Fullscreen is unavailable in this browser.');}resize();};document.addEventListener?.('fullscreenchange',()=>{resize();$('fullscreen').textContent=document.fullscreenElement?'⛶ Exit fullscreen':'⛶ Fullscreen';});

$('expandMap').onclick=()=>{const expanded=$('game').classList.toggle('battlefield-expanded');$('expandMap').textContent=expanded?'Show panels':'Expand map';$('expandMap').setAttribute('aria-pressed',String(expanded));resize();};
